plist.dict:
CFBundlePackageType
APPL
CFBundleName
{{.Info.ProductName}}
CFBundleExecutable
{{.OutputFilename}}
CFBundleIdentifier
net.vibesdr.flasher
CFBundleVersion
{{.Info.ProductVersion}}
CFBundleGetInfoString
{{.Info.Comments}}
CFBundleShortVersionString
{{.Info.ProductVersion}}
CFBundleIconFile
iconfile
LSMinimumSystemVersion
13.0.0
NSHighResolutionCapable
true
NSRemovableVolumesUsageDescription
VibeSDR Flasher backs up and writes your R36S's SD card.
NSDesktopFolderUsageDescription
VibeSDR Flasher reads the VibeSDR image from your Desktop and can save the backup there.
NSDocumentsFolderUsageDescription
VibeSDR Flasher saves the backup of your SD card in Documents › VibeSDR Backups.
NSHumanReadableCopyright
{{.Info.Copyright}}
{{if .Info.FileAssociations}}
CFBundleDocumentTypes

  {{range .Info.FileAssociations}}

    CFBundleTypeExtensions

      {{.Ext}}

    CFBundleTypeName
    {{.Name}}
    CFBundleTypeRole
    {{.Role}}
    CFBundleTypeIconFile
    {{.IconName}}

  {{end}}

{{end}}
{{if .Info.Protocols}}
CFBundleURLTypes

  {{range .Info.Protocols}}

        CFBundleURLName
        com.wails.{{.Scheme}}
        CFBundleURLSchemes

            {{.Scheme}}

        CFBundleTypeRole
        {{.Role}}

  {{end}}

{{end}}
